import{_ as a,o as n,c as e,ag as i}from"./chunks/framework.gmyryY1Z.js";const k=JSON.parse('{"title":"架构概览","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/architecture.md","filePath":"zh/guide/architecture.md","lastUpdated":null}'),p={name:"zh/guide/architecture.md"};function t(l,s,o,c,d,h){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="架构概览" tabindex="-1">架构概览 <a class="header-anchor" href="#架构概览" aria-label="Permalink to &quot;架构概览&quot;">​</a></h1><p>Fast Vue3 是一个 <strong>Vue3 Monorepo 工程平台</strong>，而非单一的 Admin 模板。其核心定位是：</p><blockquote><p>一套可复用的前端工程基础，同时集成多套主流 Admin UI 生态，作为可长期演进的前端基础设施平台。</p></blockquote><h2 id="工程分层" tabindex="-1">工程分层 <a class="header-anchor" href="#工程分层" aria-label="Permalink to &quot;工程分层&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                     apps/                           │</span></span>
<span class="line"><span>│  web-antd  web-ele  web-naive  web-arco  web-tdesign│</span></span>
<span class="line"><span>│  （各 UI 生态独立运行，各有自己的路由、布局、主题）     │</span></span>
<span class="line"><span>└─────────────────┬───────────────────────────────────┘</span></span>
<span class="line"><span>                  │ 依赖</span></span>
<span class="line"><span>┌─────────────────▼───────────────────────────────────┐</span></span>
<span class="line"><span>│                   packages/                         │</span></span>
<span class="line"><span>│  @core/shared  utils  stores  locales               │</span></span>
<span class="line"><span>│  effects/request  effects/access                    │</span></span>
<span class="line"><span>│  （业务基础层，所有 app 共享）                         │</span></span>
<span class="line"><span>└─────────────────┬───────────────────────────────────┘</span></span>
<span class="line"><span>                  │ 工程设施</span></span>
<span class="line"><span>┌─────────────────▼───────────────────────────────────┐</span></span>
<span class="line"><span>│                  internal/                          │</span></span>
<span class="line"><span>│  vite-config  tsconfig  lint-configs                │</span></span>
<span class="line"><span>│  （工程基础设施，不含业务逻辑）                        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="核心技术决策" tabindex="-1">核心技术决策 <a class="header-anchor" href="#核心技术决策" aria-label="Permalink to &quot;核心技术决策&quot;">​</a></h2><h3 id="pnpm-workspace-catalog" tabindex="-1">pnpm Workspace + Catalog <a class="header-anchor" href="#pnpm-workspace-catalog" aria-label="Permalink to &quot;pnpm Workspace + Catalog&quot;">​</a></h3><p><code>pnpm-workspace.yaml</code> 通过 <code>catalog:</code> 字段统一管理所有依赖版本：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  vue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^3.5.17</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  vite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^7.3.3</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  typescript</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^5.9.3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # ...所有 UI 库版本</span></span></code></pre></div><p>所有 workspace 包在 <code>package.json</code> 中使用 <code>catalog:</code> 引用，确保版本一致性。</p><h3 id="turbo-任务编排" tabindex="-1">Turbo 任务编排 <a class="header-anchor" href="#turbo-任务编排" aria-label="Permalink to &quot;Turbo 任务编排&quot;">​</a></h3><p><code>turbo.json</code> 定义任务依赖关系：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;persistent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>dev</code> 任务的 <code>dependsOn: [&quot;^build&quot;]</code> 确保启动任何应用前，其所有依赖包（特别是 <code>@fast-vue3/vite-config</code>）都已预先构建。</p><h3 id="vite-config-预编译策略" tabindex="-1">vite-config 预编译策略 <a class="header-anchor" href="#vite-config-预编译策略" aria-label="Permalink to &quot;vite-config 预编译策略&quot;">​</a></h3><p><code>@fast-vue3/vite-config</code> 是特殊的工程包：</p><ul><li>它被 <code>apps/</code> 中的 <code>vite.config.ts</code> 引用</li><li>Node.js 执行 <code>vite.config.ts</code> 时需要加载此包</li><li>因此它<strong>必须编译为 JS</strong>，不能直接导出 TypeScript 源码</li></ul><p>解决方案：使用 <code>tsdown</code>（基于 Rolldown）将其编译为 <code>dist/index.js</code>。</p><p>其他 <code>packages/*</code> 则直接导出 TypeScript 源码（<code>&quot;default&quot;: &quot;./src/index.ts&quot;</code>），由 Vite 在应用构建时处理。</p><h3 id="端口分配" tabindex="-1">端口分配 <a class="header-anchor" href="#端口分配" aria-label="Permalink to &quot;端口分配&quot;">​</a></h3><table tabindex="0"><thead><tr><th>应用</th><th>UI 框架</th><th>端口</th></tr></thead><tbody><tr><td>web-antd</td><td>Ant Design Vue</td><td>3001</td></tr><tr><td>web-ele</td><td>Element Plus</td><td>3002</td></tr><tr><td>web-naive</td><td>Naive UI</td><td>3003</td></tr><tr><td>web-arco</td><td>Arco Design</td><td>3004</td></tr><tr><td>web-tdesign</td><td>TDesign Vue Next</td><td>3005</td></tr></tbody></table><h2 id="应用内部结构" tabindex="-1">应用内部结构 <a class="header-anchor" href="#应用内部结构" aria-label="Permalink to &quot;应用内部结构&quot;">​</a></h2><p>每个 <code>apps/*</code> 应用采用统一的内部结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/web-{name}/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── api/</span></span>
<span class="line"><span>│   │   ├── http.ts          # createHttpClient + createRequest 实例</span></span>
<span class="line"><span>│   │   └── user/</span></span>
<span class="line"><span>│   │       └── index.ts     # 用户相关 API</span></span>
<span class="line"><span>│   ├── plugins/</span></span>
<span class="line"><span>│   │   └── {name}.ts        # UI 框架 setup 函数</span></span>
<span class="line"><span>│   ├── router/</span></span>
<span class="line"><span>│   │   └── index.ts         # 路由配置 + setupAccessGuard</span></span>
<span class="line"><span>│   ├── views/</span></span>
<span class="line"><span>│   │   ├── index.vue         # 主布局（含侧边栏、Header）</span></span>
<span class="line"><span>│   │   ├── login/</span></span>
<span class="line"><span>│   │   │   └── index.vue    # 登录页</span></span>
<span class="line"><span>│   │   └── dashboard/</span></span>
<span class="line"><span>│   │       └── index.vue    # 仪表盘页</span></span>
<span class="line"><span>│   ├── App.vue</span></span>
<span class="line"><span>│   └── main.ts</span></span>
<span class="line"><span>├── mock/</span></span>
<span class="line"><span>│   ├── helpers.ts            # Mock 响应工具</span></span>
<span class="line"><span>│   └── user.ts              # 用户接口 Mock</span></span>
<span class="line"><span>├── types/</span></span>
<span class="line"><span>│   └── env.d.ts             # 环境变量类型声明</span></span>
<span class="line"><span>├── .env                     # 基础环境变量</span></span>
<span class="line"><span>├── .env.development         # 开发环境变量</span></span>
<span class="line"><span>├── .env.production          # 生产环境变量</span></span>
<span class="line"><span>├── tsconfig.json            # 继承 @fast-vue3/tsconfig/web-app</span></span>
<span class="line"><span>└── vite.config.ts           # 使用 @fast-vue3/vite-config defineConfig</span></span></code></pre></div><h2 id="共享基础设施" tabindex="-1">共享基础设施 <a class="header-anchor" href="#共享基础设施" aria-label="Permalink to &quot;共享基础设施&quot;">​</a></h2><p>所有应用通过 <code>packages/*</code> 共享：</p><ul><li><strong>@fast-vue3/shared</strong> — 核心类型、常量（Token key、locale key 等）</li><li><strong>@fast-vue3/utils</strong> — 鉴权工具（getToken/setToken）、日期格式化、通用 helpers</li><li><strong>@fast-vue3/stores</strong> — Pinia store（useUserStore/useAppStore）+ persistedstate 插件</li><li><strong>@fast-vue3/locales</strong> — zh-CN / en-US 国际化资源</li><li><strong>@fast-vue3/request</strong> — axios 封装（createHttpClient/createRequest）</li><li><strong>@fast-vue3/access</strong> — 路由权限守卫（setupAccessGuard）+ v-access 指令</li></ul>`,27)])])}const u=a(p,[["render",t]]);export{k as __pageData,u as default};
